1	use std::collections::HashSet;
2	use std::ffi::OsStr;
3	use std::ffi::OsString;
4	
5	use clap::Id;
6	use clap_lex::OsStrExt as _;
7	
8	use super::ArgValueCandidates;
9	use super::ArgValueCompleter;
10	use super::CompletionCandidate;
11	use super::SubcommandCandidates;
12	use super::ValueCandidates;
13	use super::custom::complete_path;
14	use super::custom::possible_value_candidates;
15	
16	/// Complete the given command, shell-agnostic
17	pub fn complete(
18	    cmd: &mut clap::Command,
19	    args: Vec<OsString>,
20	    arg_index: usize,
21	    current_dir: Option<&std::path::Path>,
22	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
23	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
24	    cmd.build();
25	
26	    let raw_args = clap_lex::RawArgs::new(args);
27	    let mut cursor = raw_args.cursor();
28	    let mut target_cursor = raw_args.cursor();
29	    raw_args.seek(
30	        &mut target_cursor,
31	        clap_lex::SeekFrom::Start(arg_index as u64),
32	    );
33	    // As we loop, `cursor` will always be pointing to the next item
34	    raw_args.next_os(&mut target_cursor);
35	    debug!("complete: target_cursor={target_cursor:?}");
36	
37	    // TODO: Multicall support
38	    if !cmd.is_no_binary_name_set() {
39	        raw_args.next_os(&mut cursor);
40	    }
41	
42	    let mut current_cmd = &*cmd;
43	    let mut pos_index = 1;
44	    let mut is_escaped = false;
45	    let mut next_state = ParseState::ValueDone;
46	    // Set when an already closed word carried a value that cannot be part of
47	    // the command line (a delimiter-separated value set that is overfull, has
48	    // an empty segment, ...). Completion then reports "no completion generated"
49	    // instead of guessing at unrelated candidates.
50	    let mut is_illegal = false;
51	    // Ids of options explicitly present in `args[..arg_index]`, used to hide
52	    // conflicting candidates. Only recognized option names are recorded;
53	    // values, positionals, `--`-escaped words, default values and env values
54	    // never are.
55	    let mut explicit_opts = HashSet::<Id>::new();
56	    while let Some(arg) = raw_args.next(&mut cursor) {
57	        let current_state = next_state;
58	        next_state = ParseState::ValueDone;
59	        debug!(
60	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
61	            arg.to_value_os(),
62	        );
63	        if cursor == target_cursor {
64	            if is_illegal {
65	                return Err(std::io::Error::other("no completion generated"));
66	            }
67	            let disabled = gather_disabled_args(current_cmd, &explicit_opts);
68	            return complete_arg(
69	                &arg,
70	                current_cmd,
71	                current_dir,
72	                pos_index,
73	                is_escaped,
74	                current_state,
75	                &disabled,
76	            );
77	        }
78	
79	        if let Ok(value) = arg.to_value() {
80	            // A dangling delimiter forces this word to be the option's next
81	            // segment, never a subcommand.
82	            let open_segment = matches!(&current_state, ParseState::Opt(state) if state.open);
83	            if !open_segment {
84	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
85	                    current_cmd = next_cmd;
86	                    pos_index = 1;
87	                    continue;
88	                }
89	            }
90	        }
91	
92	        // While a dangling delimiter makes the next segment mandatory
93	        // (`--opt=a,`), a closed word may only be that segment.  An option
94	        // word (recognized or not) or `--` cannot fill it and clap rejects the
95	        // line, so completion reports an error instead of guessing a stop or a
96	        // new option. An option with `allow_hyphen_values` still accepts a
97	        // hyphen-prefixed word as the segment. A plain value word below is
98	        // consumed as the segment.
99	        if let ParseState::Opt(state) = &current_state {
100	            if state.open && !is_escaped && !opt_allows_hyphen(&current_state, &arg) {
101	                let is_option_word = arg.is_escape()
102	                    || arg.to_long().is_some()
103	                    || arg
104	                        .to_short()
105	                        .is_some_and(|short| !short.is_negative_number());
106	                if is_option_word {
107	                    is_illegal = true;
108	                }
109	            }
110	        }
111	
112	        if is_escaped {
113	            (next_state, pos_index) =
114	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
115	        } else if arg.is_escape() {
116	            is_escaped = true;
117	        } else if opt_allows_hyphen(&current_state, &arg) {
118	            match current_state {
119	                ParseState::Opt(state) => {
120	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
121	                }
122	                _ => unreachable!("else branch is only reachable in Opt state"),
123	            }
124	        } else if let Some((flag, value)) = arg.to_long() {
125	            if let Ok(flag) = flag {
126	                let opt = current_cmd.get_arguments().find(|a| {
127	                    let longs = a.get_long_and_visible_aliases();
128	                    let is_find = longs.map(|v| {
129	                        let mut iter = v.into_iter();
130	                        let s = iter.find(|s| *s == flag);
131	                        s.is_some()
132	                    });
133	                    is_find.unwrap_or(false)
134	                });
135	
136	                if let Some(opt) = opt {
137	                    explicit_opts.insert(opt.get_id().clone());
138	                    if opt.get_num_args().expect("built").takes_values() {
139	                        match value {
140	                            // A bare `--name` still expects its value as the next word.
141	                            None => next_state = ParseState::Opt(OptState::new(opt, 1)),
142	                            // A closed `--name=value` word normally ends the
143	                            // occurrence, but a dangling value delimiter with
144	                            // room for another segment keeps accepting values.
145	                            Some(value) => {
146	                                next_state = attached_opt_state(opt, value, &mut is_illegal);
147	                            }
148	                        }
149	                    }
150	                } else if pos_allows_hyphen(current_cmd, pos_index) {
151	                    (next_state, pos_index) =
152	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
153	                }
154	            }
155	        } else if let Some(short) = arg.to_short() {
156	            let (leading_flags, takes_value_opt, mut short, cluster_valid) =
157	                parse_shortflags(current_cmd, short);
158	            // Only a cluster made entirely of recognized flags records state.
159	            // Splitting an invalid short string into known and unknown members
160	            // would be guesswork and could suppress conflicting candidates, so
161	            // invalid clusters keep the existing completion behavior; clap's
162	            // parser would reject them anyway.
163	            if cluster_valid {
164	                // Every recognized flag in the cluster was explicitly supplied.
165	                for flag in leading_flags.chars() {
166	                    if let Some(opt) = current_cmd.get_arguments().find(|a| {
167	                        a.get_short_and_visible_aliases()
168	                            .is_some_and(|shorts| shorts.contains(&flag))
169	                    }) {
170	                        explicit_opts.insert(opt.get_id().clone());
171	                    }
172	                }
173	            }
174	            if let Some(opt) = takes_value_opt {
175	                if let Some(remainder) = short.next_value_os() {
176	                    // A closed `-ovalue` / `-o=value` word; advance like the
177	                    // long `--opt=value` form.
178	                    let value = remainder.strip_prefix("=").unwrap_or(remainder);
179	                    next_state = attached_opt_state(opt, value, &mut is_illegal);
180	                } else {
181	                    next_state = ParseState::Opt(OptState::new(opt, 1));
182	                }
183	            } else if pos_allows_hyphen(current_cmd, pos_index) {
184	                (next_state, pos_index) =
185	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
186	            }
187	        } else {
188	            match current_state {
189	                ParseState::ValueDone | ParseState::Pos(..) => {
190	                    (next_state, pos_index) =
191	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
192	                }
193	                ParseState::Opt(state) => {
194	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
195	                }
196	            }
197	        }
198	    }
199	
200	    Err(std::io::Error::other("no completion generated"))
201	}
202	
203	#[derive(Debug, PartialEq, Eq, Clone)]
204	enum ParseState<'a> {
205	    /// Parsing a value done, there is no state to record.
206	    ValueDone,
207	
208	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
209	    Pos((usize, usize)),
210	
211	    /// Parsing a optional flag argument
212	    Opt(OptState<'a>),
213	}
214	
215	/// Ongoing state while an option still accepts value words.
216	#[derive(Debug, PartialEq, Eq, Clone)]
217	struct OptState<'a> {
218	    opt: &'a clap::Arg,
219	    /// Ordinal of the value word about to be consumed within this occurrence.
220	    /// A bare `--name` waiting for its first value starts at `1`; this is the
221	    /// value handed to [`ArgValueCompleter::complete_at`] as `arg_index + 1`,
222	    /// so it counts shell words and is unaffected by the value delimiter.
223	    word: usize,
224	    /// Delimiter segments already closed by earlier value words, in order.
225	    used: Vec<OsString>,
226	    /// The state was reached through a dangling value delimiter, so the next
227	    /// word is another segment of this option rather than an optional stop.
228	    open: bool,
229	}
230	
231	impl<'a> OptState<'a> {
232	    fn new(opt: &'a clap::Arg, word: usize) -> Self {
233	        Self {
234	            opt,
235	            word,
236	            used: Vec::new(),
237	            open: false,
238	        }
239	    }
240	}
241	
242	/// Whether an option carries several values split by a delimiter inside one
243	/// shell word *and* bounds how many such values it accepts.
244	///
245	/// An argument with the default range of one value may still pack an arbitrary
246	/// number of delimiter segments into its single word (clap's parser allows it),
247	/// and completion preserves that legacy behavior; only multi-value arguments
248	/// count segments against their range.
249	fn is_bounded_delimited(opt: &clap::Arg) -> Option<char> {
250	    let delim = opt.get_value_delimiter()?;
251	    if opt.get_num_args().expect("built").max_values() > 1 {
252	        Some(delim)
253	    } else {
254	        None
255	    }
256	}
257	
258	/// Split a shell value on its delimiter into its closed segments.
259	///
260	/// Returns `(segments, dangling)` where `dangling` is set when the value ends
261	/// with the delimiter: the final empty piece is the segment still being typed
262	/// rather than a closed (empty and therefore invalid) segment. Splitting works
263	/// on raw [`OsStr`] bytes, so invalid UTF-8 values are handled too.
264	fn split_delimited(value: &OsStr, delim: char) -> (Vec<&OsStr>, bool) {
265	    let mut buf = [0_u8; 4];
266	    let delim_str = delim.encode_utf8(&mut buf);
267	    let mut segments: Vec<&OsStr> = value.split(delim_str).collect();
268	    let dangling = value.contains(delim_str) && segments.last().is_some_and(|last| last.is_empty());
269	    if dangling {
270	        segments.pop();
271	    }
272	    (segments, dangling)
273	}
274	
275	/// Fold one closed value word into an option's ongoing value state.
276	///
277	/// `Ok(None)` means the occurrence is complete, `Ok(Some(state))` that another
278	/// value word is accepted and `Err(())` that the word cannot be part of a valid
279	/// command line (an empty delimiter segment or more segments than the option
280	/// accepts); the latter produces "no completion generated" rather than guesses.
281	fn consume_opt_word<'a>(
282	    prior: OptState<'a>,
283	    value: &OsStr,
284	    attached: bool,
285	) -> Result<Option<OptState<'a>>, ()> {
286	    let opt = prior.opt;
287	    let range = opt.get_num_args().expect("built");
288	    let max = range.max_values();
289	    let ordinal = prior.word;
290	    let mut used = prior.used;
291	
292	    let Some(delim) = is_bounded_delimited(opt) else {
293	        // Legacy behavior: count whole shell words against the range; whatever
294	        // is packed behind a delimiter does not extend or shorten the count.
295	        // An attached value always closes the occurrence.
296	        return Ok(if !attached && ordinal < max {
297	            Some(OptState {
298	                opt,
299	                word: ordinal + 1,
300	                used,
301	                open: false,
302	            })
303	        } else {
304	            None
305	        });
306	    };
307	
308	    let mut buf = [0_u8; 4];
309	    let delim_str = delim.encode_utf8(&mut buf);
310	    let (segments, dangling) = split_delimited(value, delim);
311	    // Empty pieces are only invalid once a delimiter actually separates
312	    // segments; a bare empty value (`--opt=`) keeps its old tolerant behavior.
313	    if value.contains(delim_str) && segments.iter().any(|s| s.is_empty()) {
314	        return Err(());
315	    }
316	    let closed = used.len() + segments.len();
317	    if closed > max || (closed == max && dangling) {
318	        return Err(());
319	    }
320	    used.extend(segments.iter().map(|s| s.to_os_string()));
321	
322	    // An attached value closes the occurrence unless a dangling delimiter
323	    // still accepts another segment; a space-separated word keeps accepting
324	    // values until the range is full.
325	    let accepts_more = dangling || (!attached && closed < max);
326	    Ok(if accepts_more {
327	        Some(OptState {
328	            opt,
329	            word: ordinal + 1,
330	            used,
331	            open: dangling,
332	        })
333	    } else {
334	        None
335	    })
336	}
337	
338	/// State after a closed `--opt=value` word: `ValueDone` when the occurrence is
339	/// complete, `Opt` when a dangling delimiter still accepts another segment.
340	/// Illegal values flag the whole command line as uncompletable.
341	fn attached_opt_state<'a>(
342	    opt: &'a clap::Arg,
343	    value: &OsStr,
344	    is_illegal: &mut bool,
345	) -> ParseState<'a> {
346	    match consume_opt_word(OptState::new(opt, 1), value, true) {
347	        Ok(Some(state)) => ParseState::Opt(state),
348	        Ok(None) => ParseState::ValueDone,
349	        Err(()) => {
350	            *is_illegal = true;
351	            ParseState::ValueDone
352	        }
353	    }
354	}
355	
356	/// Advance an ongoing option occurrence by one space-separated value word.
357	fn advance_opt_value<'a>(
358	    state: OptState<'a>,
359	    value: &OsStr,
360	    is_illegal: &mut bool,
361	) -> ParseState<'a> {
362	    match consume_opt_word(state, value, false) {
363	        Ok(Some(next)) => ParseState::Opt(next),
364	        Ok(None) => ParseState::ValueDone,
365	        Err(()) => {
366	            *is_illegal = true;
367	            ParseState::ValueDone
368	        }
369	    }
370	}
371	
372	/// Result of analyzing the value word under the cursor for an option that
373	/// packs delimiter-separated values.
374	struct DelimCursor<'s> {
375	    /// Text of the segment currently being typed.
376	    current: &'s OsStr,
377	    /// Closed segments that precede it, in order.
378	    closed: Vec<&'s OsStr>,
379	    /// Everything in this shell word before the current segment, including the
380	    /// trailing delimiter, to re-prefix candidates with.
381	    prefix: &'s str,
382	}
383	
384	/// Split the cursor value of a bounded delimiter option into the segment being
385	/// edited and its already closed prefix segments.
386	///
387	/// `Ok(None)` means the option is not a bounded delimiter option (legacy
388	/// completion applies); `Err(())` means the cursor sits at an illegal segment
389	/// position (a leading/empty segment or one past the accepted number of
390	/// values), which must not produce candidates.
391	fn cursor_delimited<'s>(
392	    opt: &clap::Arg,
393	    value: &'s OsStr,
394	    prior_segments: usize,
395	) -> Result<Option<DelimCursor<'s>>, ()> {
396	    let Some(delim) = is_bounded_delimited(opt) else {
397	        return Ok(None);
398	    };
399	    let max = opt.get_num_args().expect("built").max_values();
400	    // The cursor word being edited keeps the legacy whole-word completion when
401	    // it is not valid UTF-8; earlier closed words are still tracked by bytes.
402	    let value_str = match value.to_str() {
403	        Some(s) => s,
404	        None => return Ok(None),
405	    };
406	    let mut buf = [0_u8; 4];
407	    let delim_str = delim.encode_utf8(&mut buf);
408	
409	    let Some(pos) = value_str.rfind(delim) else {
410	        return Ok(Some(DelimCursor {
411	            current: value,
412	            closed: Vec::new(),
413	            prefix: "",
414	        }));
415	    };
416	    let (prefix, current) = value_str.split_at(pos + delim.len_utf8());
417	    let closed: Vec<&str> = prefix[..prefix.len() - delim_str.len()]
418	        .split(delim)
419	        .collect();
420	    if closed.iter().any(|s| s.is_empty()) || prior_segments + closed.len() >= max {
421	        return Err(());
422	    }
423	    Ok(Some(DelimCursor {
424	        current: OsStr::new(current),
425	        closed: closed.into_iter().map(OsStr::new).collect(),
426	        prefix,
427	    }))
428	}
