546	/// Hide hidden candidates when visible ones exist, deduplicate by id and sort
547	/// into the presentation order shared by every completion source.
548	fn finalize_completions(
549	    mut completions: Vec<CompletionCandidate>,
550	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
551	    if completions.iter().any(|a| !a.is_hide_set()) {
552	        completions.retain(|a| !a.is_hide_set());
553	    }
554	    let mut seen_ids = HashSet::new();
555	    completions.retain(move |a| {
556	        if let Some(id) = a.get_id().cloned() {
557	            seen_ids.insert(id)
558	        } else {
559	            true
560	        }
561	    });
562	
563	    let mut tags = Vec::new();
564	    for candidate in &completions {
565	        let tag = candidate.get_tag().cloned();
566	        if !tags.contains(&tag) {
567	            tags.push(tag);
568	        }
569	    }
570	    completions.sort_by_key(|c| {
571	        (
572	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
573	            c.get_display_order(),
574	        )
575	    });
576	
577	    Ok(completions)
578	}
