630	/// Completion at a space-separated option value word tracked by `state`.
631	fn complete_separate_opt_value(
632	    value: Result<&str, &OsStr>,
633	    state: &OptState<'_>,
634	    current_dir: Option<&std::path::Path>,
635	) -> Result<Vec<CompletionCandidate>, ()> {
636	    let value_os = match value {
637	        Ok(value) => OsStr::new(value),
638	        Err(value_os) => value_os,
639	    };
640	    let used: Vec<&OsStr> = state.used.iter().map(OsString::as_os_str).collect();
641	    complete_segment_value(
642	        value_os,
643	        state.opt,
644	        state.used.len(),
645	        &used,
646	        state.word.saturating_sub(1),
647	        current_dir,
648	    )
649	}
