651	/// Complete the inline value carried by the cursor's option word.
652	///
653	/// This covers `--name=value` as well as short clusters with an attached
654	/// value, e.g. `-ovalue` and `-o=value` (including leading flags, `-abovalue`).
655	/// It returns the option's value candidates, re-prefixed with the exact
656	/// option spelling, when the cursor is inside such a value.  The whole word is
657	/// consumed by its option: nothing after `=` or past the taking flag takes
658	/// part in option-name, subcommand or positional completion, and the word is
659	/// not yet part of the conflict set.
660	///
661	/// A bare `--name`/`-o` whose value is still a separate word completes
662	/// normally, as does an unknown long name, a recognized option that takes no
663	/// value and anything else that cannot be recognized: `None` preserves the
664	/// existing failure semantics rather than guessing a split.
665	///
666	/// `Some(Err(()))` means the recognized word is an illegal value position for
667	/// a bounded delimiter option (an empty segment or a segment past the accepted
668	/// number of values) and must yield "no completion generated".
669	fn complete_inline_option_value(
670	    arg: &clap_lex::ParsedArg<'_>,
671	    cmd: &clap::Command,
672	    current_dir: Option<&std::path::Path>,
673	    disabled: &HashSet<Id>,
674	) -> Option<Result<Vec<CompletionCandidate>, ()>> {
675	    if let Some((flag, value)) = arg.to_long() {
676	        let flag = flag.ok()?;
677	        // A bare `--name` has no attached value and is completed as an option name.
678	        let value = value?;
679	        let opt = cmd.get_arguments().find(|a| {
680	            a.get_long_and_visible_aliases()
681	                .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
682	        })?;
683	        if !opt.get_num_args().expect("built").takes_values() {
684	            return None;
685	        }
686	        if disabled.contains(opt.get_id()) {
687	            return Some(Ok(Vec::new()));
688	        }
689	        let prefix = format!("--{flag}=");
690	        return Some(
691	            complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
692	                values
693	                    .into_iter()
694	                    .map(|comp| comp.add_prefix(&prefix))
695	                    .collect()
696	            }),
697	        );
698	    }
699	
700	    let short = arg.to_short()?;
701	    if short.is_negative_number() {
702	        return None;
703	    }
704	    let (leading_flags, opt, mut value_flags, _) = parse_shortflags(cmd, short);
705	    let opt = opt?;
706	
707	    // Detect an attached value: once the cluster reaches its value-taking
708	    // flag, everything left is the value, optionally introduced by `=`.  With
709	    // no remainder and no `=` (`-o`), the word is left to the regular option
710	    // completion, which already offers inline values.
711	    let mut peek = value_flags.clone();
712	    let has_equal = matches!(peek.next_flag(), Some(Ok('=')));
713	    if !has_equal && value_flags.is_empty() {
714	        return None;
715	    }
716	    if has_equal {
717	        // Consume the `=` so the remainder is the bare value (possibly empty
718	        // for `-o=`), matching the space-separated empty-value position.
719	        value_flags.next_flag();
720	    }
721	    if disabled.contains(opt.get_id()) {
722	        return Some(Ok(Vec::new()));
723	    }
724	    let value = value_flags.next_value_os().unwrap_or(OsStr::new(""));
725	    let sep = if has_equal { "=" } else { "" };
726	    let prefix = format!("-{leading_flags}{sep}");
727	    Some(
728	        complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
729	            values
730	                .into_iter()
731	                .map(|comp| comp.add_prefix(&prefix))
732	                .collect()
733	        }),
734	    )
735	}
