936	fn rsplit_delimiter<'s, 'o>(
937	    value: Result<&'s str, &'o OsStr>,
938	    delimiter: Option<char>,
939	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
940	    let delimiter = delimiter?;
941	    let value = value.ok()?;
942	    let pos = value.rfind(delimiter)?;
943	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
944	    Some((Some(prefix), Ok(value)))
945	}
