977	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
978	    debug!(
979	        "complete_subcommand: cmd={:?}, value={:?}",
980	        cmd.get_name(),
981	        value
982	    );
983	
984	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
985	        .into_iter()
986	        .filter(|x| x.get_value().starts_with(value))
987	        .collect();
988	    if cmd.is_allow_external_subcommands_set() {
989	        let external_completer = cmd.get::<SubcommandCandidates>();
990	        if let Some(completer) = external_completer {
991	            scs.extend(complete_value_candidates_str(
992	                value,
993	                completer.value_candidates(),
994	            ));
995	        }
996	    }
997	
998	    scs.sort();
999	    scs.dedup();
1000	    scs
1001	}
