1003	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
1004	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
1005	fn longs_and_visible_aliases(
1006	    p: &clap::Command,
1007	    disabled: &HashSet<Id>,
1008	) -> Vec<CompletionCandidate> {
1009	    debug!("longs: name={}", p.get_name());
1010	
1011	    p.get_arguments()
1012	        .filter(|a| !disabled.contains(a.get_id()))
1013	        .filter_map(|a| {
1014	            a.get_long_and_visible_aliases().map(|longs| {
1015	                longs
1016	                    .into_iter()
1017	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
1018	            })
1019	        })
1020	        .flatten()
1021	        .collect()
