1129	/// Parse the short flags and find the first `takes_values` option.
1130	///
1131	/// The returned bool is `true` only when every scanned cluster member was a
1132	/// recognized option. Anything after the first value-taking option is the
1133	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
1134	/// characters make the result `false`.
1135	fn parse_shortflags<'c, 's>(
1136	    cmd: &'c clap::Command,
1137	    mut short: clap_lex::ShortFlags<'s>,
1138	) -> (
1139	    String,
1140	    Option<&'c clap::Arg>,
1141	    clap_lex::ShortFlags<'s>,
1142	    bool,
1143	) {
1144	    let takes_value_opt;
1145	    let mut leading_flags = String::new();
1146	    let mut cluster_valid = true;
1147	    // Find the first takes_values option.
1148	    loop {
1149	        match short.next_flag() {
1150	            Some(Ok(opt)) => {
1151	                leading_flags.push(opt);
1152	                let found = cmd.get_arguments().find(|a| {
1153	                    let shorts = a.get_short_and_visible_aliases();
1154	                    let is_find = shorts.map(|v| {
1155	                        let mut iter = v.into_iter();
1156	                        let c = iter.find(|c| *c == opt);
1157	                        c.is_some()
1158	                    });
1159	                    is_find.unwrap_or(false)
1160	                });
1161	                if let Some(opt) = found {
1162	                    if opt.get_num_args().expect("built").takes_values() {
1163	                        takes_value_opt = Some(opt);
1164	                        break;
1165	                    }
1166	                } else {
1167	                    cluster_valid = false;
1168	                }
1169	            }
1170	            Some(Err(_)) => {
1171	                cluster_valid = false;
1172	                takes_value_opt = None;
1173	                break;
1174	            }
1175	            None => {
1176	                takes_value_opt = None;
1177	                break;
1178	            }
1179	        }
1180	    }
1181	
1182	    (leading_flags, takes_value_opt, short, cluster_valid)
1183	}
