1236	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1237	    cmd.get_positionals()
1238	        .find(|a| a.get_index() == Some(pos_index))
1239	        .map(|p| p.is_allow_hyphen_values_set())
