1243	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1244	    let val = arg.to_value_os();
1245	    if val.starts_with("-") {
1246	        if let ParseState::Opt(state) = state {
1247	            return state.opt.is_allow_hyphen_values_set();
1248	        }
1249	    }
1250	
1251	    false
1252	}
