1254	/// Arguments that must not be offered because they conflict with an explicitly
1255	/// present option. The present options themselves are never disabled.
1256	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
1257	    let mut disabled = HashSet::new();
1258	    if explicit.is_empty() {
1259	        return disabled;
1260	    }
1261	    for arg in cmd.get_arguments() {
1262	        if explicit.contains(arg.get_id()) {
1263	            // A present option hides everything it conflicts with ...
1264	            for id in arg_direct_conflicts(cmd, arg) {
1265	                if !explicit.contains(&id) {
1266	                    disabled.insert(id);
1267	                }
1268	            }
1269	        } else {
1270	            // ... and is hidden when either side declares the conflict.
1271	            if arg_direct_conflicts(cmd, arg)
1272	                .iter()
1273	                .any(|id| explicit.contains(id))
1274	            {
1275	                disabled.insert(arg.get_id().clone());
1276	            }
1277	        }
1278	    }
1279	    disabled
1280	}
1281	
1282	/// Conflict partners of `arg`, following the same rules as clap's parser:
1283	/// - the argument's own `conflicts_with` / `conflicts_with_all`
1284	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
1285	/// - the other members of non-`multiple` groups
1286	///
1287	/// Group ids are expanded to their argument members.
1288	/// `overrides_with` relationships are intentionally not considered.
1289	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
1290	    let mut conflicts = arg
1291	        .get_conflicts_with()
1292	        .map(ToOwned::to_owned)
1293	        .collect::<HashSet<_>>();
1294	    for group in cmd.get_groups() {
1295	        let members = unroll_group(cmd, group.get_id());
1296	        if !members.iter().any(|m| m == arg.get_id()) {
1297	            continue;
1298	        }
1299	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
1300	        if !group.is_multiple_set() {
1301	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
1302	        }
1303	    }
1304	    conflicts
1305	        .iter()
1306	        .flat_map(|id| unroll_group(cmd, id))
1307	        .collect()
1308	}
1309	
1310	/// Resolve an argument or group id to its argument members.
1311	/// Unknown ids resolve to themselves.
1312	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
1313	    let mut pending = vec![id.clone()];
1314	    let mut args = Vec::new();
1315	    while let Some(id) = pending.pop() {
1316	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
1317	            if !args.contains(&id) {
1318	                args.push(id);
1319	            }
1320	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
1321	            pending.extend(group.get_args().map(ToOwned::to_owned));
1322	        } else if !args.contains(&id) {
1323	            args.push(id);
1324	        }
1325	    }
1326	    args
1327	}
