use clap::{builder::PossibleValue, Command};

fn command() -> Command {
    Command::new("fmt")
        .arg(
            clap::Arg::new("format")
                .long("format")
                .visible_alias("fmt")
                .short('f')
                .num_args(1..=2)
                .value_parser([
                    PossibleValue::new("json"),
                    PossibleValue::new("yaml"),
                    PossibleValue::new("toml"),
                ])
                .value_delimiter(','),
        )
        .arg(
            clap::Arg::new("raw")
                .long("raw")
                .short('r')
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("format"),
        )
        .arg(clap::Arg::new("dir").value_parser(["src", "dst"]))
}

fn complete(args: &str) -> String {
    let mut cmd = command();
    let mut raw = vec![std::ffi::OsString::from(cmd.get_name())];
    if let Some((prior, _)) = args.split_once("[TAB]") {
        raw.extend(prior.split_whitespace().map(From::from));
        if prior.ends_with(char::is_whitespace) {
            raw.push(std::ffi::OsString::default());
        }
    }
    let i = raw.len() - 1;
    match clap_complete::engine::complete(&mut cmd, raw, i, None) {
        Ok(v) => v
            .into_iter()
            .map(|c| c.get_value().to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join("\n"),
        Err(e) => format!("ERR: {e}"),
    }
}

