fn probe() {
    for input in [
        "--format=json,yaml -[TAB]",
        "--format=json,yaml --r[TAB]",
        "--format=json,yaml -r[TAB]",
        "--format=json,yaml [TAB]",
        "--format json [TAB]",
        "--format json, [TAB]",
        "--format=json, [TAB]",
        "-- [TAB]",
        "--fmt=json, [TAB]",
        "-fjson, [TAB]",
    ] {
        println!("--- {input}");
        println!("{}", complete(input));
    }
}

